{"packet_id":"D034-01","doc_id":"D034","jurisdiction":"Hoboken, NJ","category":"rent_increase_limits","lifecycle":"enacted","title":"Hoboken mandatory disclosures for rent increases over 10%","requirement":"A residential landlord who raises rent more than 10% on renewal of a lease with a current tenant year over year must give the tenant written disclosures — an itemized cost breakdown, whether a rent algorithm was used, notice of the right to sue, and Division of Housing contact information — before the increase takes effect.","key_value":"increase over 10%","coverage_conditions":"All residential landlords seeking to increase rent by more than 10% upon renewal of a lease with a current tenant year over year.","applicability":{"conditions":[],"per_tenancy":"Rent increase of more than 10% on renewal of a lease with a current tenant year over year","coverage_quotes":[]},"exemptions":null,"penalty":"Fine not exceeding $1,000 per incident for failing to provide the disclosures.","effective_date":null,"valid_through":null,"citation":"Hoboken Mun. Code § 158-1","quoted_span":"All residential landlords seeking to increase rent by more than 10% upon a renewal of a lease with a current tenant year over year shall be required to make the following disclosures to existing tenants either in the lease upon renewal (must be clearly indicated on the first page) or on a form provided by the Hoboken Division of Housing prior to the increase being implemented:","interaction":null,"relations":[],"confidence":0.9,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D034-01","doc_id":"D034","jurisdiction":"Hoboken, NJ","category":"algorithmic_rent_setting","lifecycle":"enacted","title":"Hoboken algorithmic rent fixing prohibition","requirement":"A landlord renting a residential dwelling unit in Hoboken may not price fix using algorithmic pricing, meaning software, algorithms or data-sharing platforms that collect and analyze nonpublic competitor information from other lessors to coordinate, recommend or implement rental prices, lease terms or occupancy levels.","key_value":null,"coverage_conditions":"Landlords renting any residential dwelling unit in Hoboken; a residential dwelling unit is any primary residence excluding medical/long-term care or detention facilities.","applicability":{"conditions":[],"per_tenancy":null,"coverage_quotes":[]},"exemptions":"Medical/long-term care and detention facilities are excluded from the definition of residential dwelling unit.","penalty":"Penalties under N.J.S.A. 40:49-5, or a fine not exceeding $2,000, or community service not exceeding 90 days.","effective_date":null,"valid_through":null,"citation":"Hoboken Mun. Code § 158-2","quoted_span":"Landlords who rent any residential dwelling unit (defined as any primary residence excluding medical/long-term care or detention facilities) in the City of Hoboken are prohibited from price fixing using algorithmic pricing.","interaction":null,"relations":[],"confidence":0.9,"conflict_flag":false,"conflict_note":null}
